      <head>
        <meta charset="utf-8" />
        <style>
          @font-face {
            font-family: 'Inter Variable';
            font-style: normal;
            font-weight: 100 900;
            src: url(<%= @font_data_uri %>) format('woff2');
          }
          /* Hex rather than Noora tokens, as on the docs card: headless
             Chrome does not resolve oklch() reliably here. */
          * { margin: 0; padding: 0; box-sizing: border-box; }
          html, body {
            width: 1920px;
            height: 1080px;
            overflow: hidden;
            font-family: 'Inter Variable', sans-serif;
            color-scheme: dark;
            background: #0E0E0E;
          }
          .content {
            position: absolute;
            left: 76px;
            top: 140px;
            width: 1768px;
          }
          .eyebrow {
            font-size: 48px;
            line-height: 48px;
            letter-spacing: -0.01em;
            color: #8366FF;
          }
          .title {
            margin-top: 40px;
            font-size: 136px;
            font-weight: 400;
            line-height: 136px;
            letter-spacing: -0.03em;
            color: #FDFDFD;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
          }
          .stats {
            display: flex;
            gap: 120px;
            margin-top: 120px;
          }
          .stat-value {
            font-size: 120px;
            font-weight: 500;
            line-height: 120px;
            letter-spacing: -0.03em;
            color: #FDFDFD;
            font-variant-numeric: tabular-nums;
          }
          .stat-label {
            margin-top: 24px;
            font-size: 44px;
            line-height: 44px;
            color: #C7CCD1;
          }
          .footer {
            position: absolute;
            inset: 0;
            width: 1920px;
            height: 1080px;
          }
          .brand {
            position: absolute;
            right: 77px;
            bottom: 66px;
            font-size: 58px;
            line-height: 58px;
            letter-spacing: -0.02em;
            color: #FDFDFD;
          }
        </style>
      </head>
      <body>
        <div class="content">
          <div class="eyebrow">{@upstream_handle} on Tuist</div>
          <div class="title">{@name}</div>
          <div class="stats">
            <div :for={{label, value} <- @stats}>
              <div class="stat-value">{value}</div>
              <div class="stat-label">{label}</div>
            </div>
          </div>
        </div>
        <svg
          class="footer"
          viewBox="0 0 1920 1080"
