    """
  end

  @doc """
  The card's HTML. `stats` is a list of `{label, value}` pairs, already
  formatted, in display order.
  """
  def render_html(opts) do
    fonts_dir = Keyword.fetch!(opts, :fonts_dir)
    font_base64 = fonts_dir |> Path.join("InterVariable.woff2") |> File.read!() |> Base.encode64()

    assigns = %{
      name: Keyword.fetch!(opts, :name),
      upstream_handle: Keyword.fetch!(opts, :upstream_handle),
      stats: Keyword.fetch!(opts, :stats),
      font_data_uri: "data:font/woff2;base64,#{font_base64}"
    }

    "<!DOCTYPE html>" <> (assigns |> card() |> Safe.to_iodata() |> IO.iodata_to_binary())
  end
end
